// Browser-only stand-in for the Tauri backend so the UI can be developed with `npm run dev`.
// Loads src/dev/snapshot.json if present (generated by the `real_machine` smoke test with SKILLSHELF_DUMP).

import type { ActionRequest, Changelog, CheckResult, Environment, Item, JobEvent, ScanResult, Settings } from "../types";

const snapshots = import.meta.glob<{ default: CheckResult }>("./snapshot.json");
const listeners = new Set<(e: JobEvent) => void>();
let items: Item[] = [];
let settings: Settings = { projects: [], autoCheck: true };
let job = 1;
const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function load(): Promise<Item[]> {
  const loader = snapshots["./snapshot.json"];
  return loader ? (await loader()).default.items : [];
}

const hoursAgo = (h: number) => new Date(Date.now() - h * 3_600_000).toISOString();
const sha = (seed: string, n: number) =>
  Array.from({ length: 40 }, (_, i) => "0123456789abcdef"[(seed.charCodeAt(i % seed.length) * (i + 7) + n * 31) % 16]).join("");
const commits = (repo: string, seed: string, messages: string[]) =>
  messages.map((message, n) => {
    const s = sha(seed, n);
    return { sha: s, date: hoursAgo(6 + n * 19), message, url: `https://github.com/${repo}/commit/${s}` };
  });
let rateLimitedOnce = false;

/** Sample changelogs covering each state the detail panel can show. */
function mockChangelog(item: Item): Changelog {
  const empty = { label: "", entries: [], total: 0, sections: [], sectionsLabel: null, moreUrl: null, note: null, retryable: false };
  if (item.source === "synced")
    return { ...empty, note: "Your claude.ai organization updates this plugin and doesn't publish what changed." };
  if (item.source === "local" || item.source === "project")
    return { ...empty, note: "No installer tracks this skill, so there's no upstream history to compare with." };
  if (item.source === "marketplace") {
    const repo = item.repoUrl?.replace("https://github.com/", "") ?? "example/marketplace";
    const sections = [
      {
        version: item.latest,
        title: `${item.latest} (2026-10-15)`,
        body: [
          "### Features",
          "- **router:** route cost questions to the `cost-audit` lane",
          "- Add golden path for serverless ComfyUI ([#86](https://github.com/example/repo/pull/86))",
          "",
          "### Bug Fixes",
          "- Retry pod creation when capacity is briefly unavailable",
        ].join("\n"),
      },
      {
        version: "1.7.3",
        title: "1.7.3 (2026-10-14)",
        body: "### Documentation\n- Clarify how network volumes attach to serverless workers",
      },
      { version: "1.7.0", title: "1.7.0 (2026-10-09)", body: "### Features\n- Bundle the hosted MCP server" },
      { version: "1.6.0", title: "1.6.0 (2026-10-08)", body: "- Template repair for ComfyUI workflows" },
    ];
    if (item.name.includes("ui-ux"))
      return {
        ...empty,
        label: "Commits in the marketplace that touched this plugin",
        sections: sections.slice(0, 2),
        sectionsLabel: "CHANGELOG.md",
        note: "The installed commit isn't in the local marketplace copy, so Skillshelf can't tell which commits are new.",
      };
    const entries = commits(repo, item.id, [
      "docs(model-caching): load volume-backed models via VolumeCache (#86)",
      "feat(router): send cost questions to the cost-audit lane",
      "fix(pod-doctor): read worker logs before restarting a pod",
      "chore(release): 1.7.3",
      "docs: explain network volume regions",
      "feat(templates): repair missing ComfyUI custom nodes",
      "fix(flash): pass the endpoint id through to job polling",
      "refactor: share the GPU catalog lookup between lanes",
      "test: cover serverless golden paths",
      "chore(release): 1.7.0",
    ]);
    return {
      ...empty,
      label: "Commits in the marketplace that touched this plugin",
      entries,
      total: 26,
      sections: item.name.includes("understand") ? [] : sections,
      sectionsLabel: "CHANGELOG.md",
      moreUrl: `https://github.com/${repo}/commits/HEAD/plugins/${item.name}`,
    };
  }
  if (item.source === "skillsCli") {
    if (item.name === "scenario-godot-expert" && !rateLimitedOnce) {
      rateLimitedOnce = true;
      throw "GitHub rate limit reached. Sign in with `gh auth login` or set GITHUB_TOKEN.";
    }
    const repo = item.origin ?? "example/skills";
    const all = [
      "chore(skills): storyboards are a board of stills with one page format (#5599)",
      "fix(skills): reject occlusion timeout before verdict (#5491)",
      "feat(cli): save check, snapshot and render artifacts per revision (#5522)",
      "docs(skills): fix frame-worker contract, lint codes and stale references (#5515)",
    ];
    const entries = commits(repo, item.id, all.slice(0, 1 + (item.name.length % all.length)));
    return {
      ...empty,
      label: "Commits that touched this skill since your last update",
      entries,
      total: entries.length,
      moreUrl: `https://github.com/${repo}/commits/HEAD/skills/${item.name}`,
    };
  }
  return { ...empty, note: "There's nothing to compare this item against." };
}

export const mockApi = {
  scan: async (): Promise<ScanResult> => {
    await wait(400);
    items = (await load()).map((i) => ({ ...i, status: "unchecked", latest: null, statusDetail: null }));
    return { items, warnings: [], scannedAt: Date.now() };
  },
  checkUpdates: async (): Promise<CheckResult> => {
    await wait(1200);
    const checked = await load();
    items = items.map((i) => checked.find((c) => c.id === i.id) ?? i);
    return { items, warnings: [], checkedAt: Date.now() };
  },
  runActions: async (requests: ActionRequest[]) =>
    requests.map((r) => {
      const item = items.find((i) => i.id === r.itemId)!;
      const base = { jobId: job++, itemId: item.id, itemName: item.name, action: r.action, line: null, message: null, confirm: null };
      const emit = (e: Partial<JobEvent>, ms: number) =>
        setTimeout(() => listeners.forEach((l) => l({ ...base, state: "queued", ...e })), ms);
      emit({ state: "queued" }, 0);
      emit({ state: "running" }, 300);
      emit({ state: "log", line: `mock: ${r.action} ${item.name}` }, 600);
      emit(item.name.includes("runpod") ? { state: "failed", message: "Mock failure" } : { state: "success", message: "Done (mock)" }, 1200);
      return { jobId: base.jobId, itemId: item.id };
    }),
  openFolder: async () => {},
  openRepo: async () => {},
  changelog: async (itemId: string): Promise<Changelog> => {
    await wait(500);
    return mockChangelog(items.find((i) => i.id === itemId)!);
  },
  openChangelogLink: async (_itemId: string, url: string) => {
    window.open(url, "_blank", "noopener");
  },
  getSettings: async () => settings,
  saveSettings: async (s: Settings) => {
    settings = s;
  },
  environment: async (): Promise<Environment> => ({
    claudeDir: "~/.claude",
    claude: "claude",
    npx: "npx",
    git: "git",
    gh: null,
    os: "browser",
    version: "dev",
  }),
  pickFolder: async () => null,
  onJob: async (cb: (e: JobEvent) => void) => {
    const listener = (e: JobEvent) => cb(e);
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
};
